import { Spin } from "@arco-design/web-react";
import React, { useEffect, useMemo, useState } from "react";
import { HashRouter, Redirect, Route, Switch, useHistory, useParams } from "react-router-dom";
import store from "@/store/dev";
import { beforLogin } from "@/layout/login";
import { App } from "@code/App";
import ajax from "@/utils/ajax";
import project from "@/store/project";
import Settings, { settingStore } from "./components/Setting";
import EnvConfig from "./components/EnvConfig";
import dir from "@/store/dir";


/**
 *  插件预览
 */
const Index = beforLogin(() => {
    const params: any = useParams();
    const { id, version } = params;
    const [isReady, setIsReady] = useState(false);

    useEffect(() => {
        // 插件登陆
        project.getProjectInfo(id).then(async () => {
            if(version){
                await import(dir.project.getBuild(id, version)).then((res) => {
                    store.setPluginData(res.default);
                })
            }else {
                await ajax.post('/project/projectInformation', { projectId: id }).then((res) => {
                    store.setPluginData(res)
                })
            }
            setIsReady(true);
        })
    },[])

    const basename = useMemo(() => {
        if(version) return `/project-v/${id}/${version}`;
        return `/project-view/${id}`;
    },[])



    return (
        <HashRouter basename={basename} >
            <EnvConfig />
            {isReady ?<App /> : <Spin loading><div style={{ width: '100vw', height: 200 }}></div></Spin>}
            {isReady? <Settings /> : null}
        </HashRouter>
    )
})


export default Index;
